cardCss:
.checkin-card {
    position: relative;
    overflow: hidden;
    background: #ffffff;
    border-radius: 16px;
    box-shadow: 0 4px 20px rgba(52, 211, 153, 0.14);
    margin-bottom: 20px;
    transition: transform 0.25s, box-shadow 0.25s;
}
.checkin-topbar { height: 6px; background: #34d399; }

/* 1) 今日待打卡 —— 核心活力卡片 */
.checkin-card.today {
    background: #ffffff;
    box-shadow: 0 4px 20px rgba(52, 211, 153, 0.14);
}
.checkin-card.today:hover {
    transform: translateY(-4px) scale(1.01);
    box-shadow: 0 8px 28px rgba(52, 211, 153, 0.20);
}
.checkin-card.today .checkin-topbar { background: #34d399; }

/* 2) 未到日期 / 待解锁 */
.checkin-card.future {
    background: #f5f3fc;
    box-shadow: none;
}
.checkin-card.future .checkin-topbar { background: #c4b5fd; }

/* 3) 已过期任务 */
.checkin-card.past {
    background: #efefef;
    box-shadow: none;
}
.checkin-card.past .checkin-topbar { background: #cccccc; }

/* 完成态（今日已打卡） */
.checkin-card.done {
    background: #d1fae5;
    box-shadow: 0 4px 20px rgba(34, 197, 94, 0.14);
}
.checkin-card.done .checkin-topbar { background: #34d399; }
.checkin-card.done:hover { transform: none; box-shadow: 0 4px 20px rgba(34, 197, 94, 0.14); }

.checkin-body { padding: 18px 20px 20px; }

/* 第一行：日期 + 标签 横向左右布局 */
.checkin-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 14px;
    flex-wrap: nowrap;
}
.checkin-date {
    display: inline-flex; align-items: center; gap: 8px;
    font-size: 30px; font-weight: 700; color: #1f2937;
    white-space: nowrap; flex-shrink: 0;
}
.checkin-date i { font-size: 26px; color: #f97316; }
.checkin-card.future .checkin-date i { color: #8b5cf6; }
.checkin-card.past .checkin-date i { color: #6b7280; }
.checkin-card.future .checkin-date, .checkin-card.past .checkin-date { color: #919191; }

/* 胶囊标签 */
.checkin-note {
    font-size: 14px;
    border-radius: 999px;
    padding: 5px 12px;
    background: #d1fae5;
    color: #065f46;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    min-width: 0;
}
.checkin-card.future .checkin-note { background: #ede9fe; color: #6d28d9; }
.checkin-card.past .checkin-note { background: #e5e7eb; color: #6b7280; }

/* 状态文字 */
.checkin-status {
    font-size: 16px; color: #919191;
    margin-bottom: 22px;
    min-height: 22px;
}
.checkin-card.done .checkin-status { color: #065f46; }

/* 打卡按钮 */
.checkin-actions { display: flex; }
.checkin-actions .action-btn {
    border: none; cursor: pointer;
    display: inline-flex; align-items: center; justify-content: center; gap: 10px;
    padding: 13px 40px; border-radius: 999px;
    font-size: 16px; font-weight: 600;
    color: #fff;
    background: linear-gradient(135deg, #22c55e, #10b981);
    box-shadow: 0 4px 14px rgba(34, 197, 94, 0.30);
    transition: transform 0.2s, box-shadow 0.2s;
}
.checkin-actions .action-btn i { font-size: 18px; }
.checkin-actions .action-btn:hover {
    transform: scale(1.04);
    box-shadow: 0 8px 24px rgba(34, 197, 94, 0.45);
}
.checkin-actions .action-btn:active {
    animation: checkinPop 0.4s;
}
@keyframes checkinPop {
    0% { transform: scale(1); }
    50% { transform: scale(1.08); }
    100% { transform: scale(1); }
}

/* 完成态按钮：锁定 */
.checkin-actions .action-btn[disabled],
.checkin-actions .action-btn.is-active {
    background: #d1fae5;
    color: #065f46;
    box-shadow: none;
    cursor: not-allowed;
}
.checkin-actions .action-btn[disabled]:hover,
.checkin-actions .action-btn.is-active:hover { transform: none; box-shadow: none; }

/* 未到日期 / 已过期：无按钮 */
.checkin-card.future .checkin-actions .action-btn,
.checkin-card.past .checkin-actions .action-btn {
    display: none;
}

cardJs:
(function () {
    'use strict';
    function todayStr() {
        var d = new Date();
        var m = String(d.getMonth() + 1).padStart(2, '0');
        var day = String(d.getDate()).padStart(2, '0');
        return d.getFullYear() + '-' + m + '-' + day;
    }
    window.cardTemplate = {
        name: 'Check-in Date Card',
        fields: [
            { key: 'date', label: '日期', hideable: false },
            { key: 'note', label: '说明' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(key) { return hidden.has && hidden.has(key); }
            function wrap(key, content) { return isHidden(key) ? '' : content; }
            var done = data.is_unknown === 1;
            var today = todayStr();
            var dateStr = d.date || '';
            var stateClass = '';
            var statusText = '';
            var dateIcon = 'fa-calendar';
            var btnLabel = '';
            var btnHtml = '';
            if (dateStr === today) {
                if (done) {
                    stateClass = 'today done';
                    statusText = '今日完成';
                    dateIcon = 'fa-fire';
                    btnHtml = '<button class="action-btn checkin-btn is-active" disabled><i class="fa-solid fa-circle-check"></i><span>打卡完成</span></button>';
                } else {
                    stateClass = 'today';
                    statusText = '今日待完成';
                    dateIcon = 'fa-fire';
                    btnHtml = '<button class="action-btn checkin-btn" data-action="checkin" data-tooltip="打卡"><i class="fa-solid fa-check"></i><span>今日打卡</span></button>';
                }
            } else if (dateStr && dateStr > today) {
                stateClass = 'future';
                statusText = '待解锁任务';
                dateIcon = 'fa-lock';
                btnHtml = '';
            } else if (dateStr && dateStr < today) {
                stateClass = done ? 'past done' : 'past';
                statusText = '已过期';
                dateIcon = 'fa-calendar';
                btnHtml = '';
            }
            var noteHtml = wrap('note', (d.note ? '<span class="checkin-note">' + (d.note || '') + '</span>' : ''));
            return '<div class="checkin-card ' + stateClass + '" data-card-id="' + data.id + '">' +
                '<div class="checkin-topbar"></div>' +
                '<div class="checkin-body">' +
                '<div class="checkin-row">' +
                wrap('date', '<span class="checkin-date"><i class="fa-solid ' + dateIcon + '"></i>' + (d.date || '') + '</span>') +
                noteHtml +
                '</div>' +
                '<div class="checkin-status">' + statusText + '</div>' +
                '<div class="checkin-actions">' + btnHtml + '</div>' +
                '</div>' +
                '</div>';
        },
init: function (cardElement, cardData, api) {
            var btn = cardElement.querySelector('[data-action="checkin"]');
            if (!btn) return;
            if (btn.disabled) return;
            btn.addEventListener('click', function () {
                if (api.confirmDialog) {
                    api.confirmDialog(btn, '确认今日打卡？', function () { doCheckin(); });
                } else {
                    if (!window.confirm('确认今日打卡？')) return;
                    doCheckin();
                }
            });
            function doCheckin() {
                btn.disabled = true;
                api.toggleMark().then(function (d) {
                    if (d.success) {
                        if (d.is_unknown === 1) api.track('check_in');
                        api.rerender();
                    } else {
                        btn.disabled = false;
                    }
                });
            }
        },
        update: function (cardElement, cardData, api) {
            var p = cardElement.parentElement;
            if (p) { cardElement.outerHTML = this.render('', cardData, api); }
        }
    };
})();
